@@ -1900,9 +1900,10 @@
 	flog(LOG_ERR, "swap_out: impossibile tradurre stack di processo %u", pid);
 	return false;
 }

-natq* src = ptr_cast<natq>(pa + DIM_PAGINA);
+paddr page_frame = pa & ~natq(DIM_PAGINA - 1);
+natq* src = ptr_cast<natq>(page_frame + DIM_PAGINA);
 memcpy(buf, src, DIM_USR_STACK);

